  1	#!/usr/bin/env node
  2	/**
  3	 * Fan the canonical inventory out to every consumer config.
  4	 *
  5	 *   inventory.json  ->  xx-stack/runtime/platforms.json                 (TS registry)
  6	 *                   ->  opencode-orchestration/opencode/platforms.json  (TS registry)
  7	 *                   ->  hermes-orchestration/config/orchestration.json  (lanes block only)
  8	 *
  9	 * A machine is described ONCE, with its hardware and the runtimes installed on
 10	 * it. Each (machine x runtime) pair becomes a host in the TS registries and a
 11	 * lane in Hermes, inheriting the machine's hardware and execution policy. That
 12	 * is the redundancy this removes: previously Skippy's GPU block was written
 13	 * twice in the TS registry and its endpoints a third time in Hermes.
 14	 *
 15	 * Usage:
 16	 *   node xx-stack/scripts/generate-registries.mjs           # write
 17	 *   node xx-stack/scripts/generate-registries.mjs --check   # fail if stale
 18	 */
 19	import fs from "node:fs";
 20	import path from "node:path";
 21	import { fileURLToPath } from "node:url";
 22	
 23	const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
 24	const inventoryPath = path.join(repoRoot, "inventory.json");
 25	const checkOnly = process.argv.includes("--check");
 26	
 27	/**
 28	 * How each runtime kind maps onto endpoints, providers, and lane families.
 29	 *
 30	 * endpointFamily     — TS registry. Ollama is inspected via /api/tags, so it is
 31	 *                      its own family there.
 32	 * hermesEndpointType — Hermes. It only distinguishes `hermes_cli` from HTTP and
 33	 *                      dials /v1/chat/completions for everything else, so every
 34	 *                      HTTP runtime is openai_compatible on that side.
 35	 */
 36	const RUNTIMES = {
 37	  ollama: {
 38	    hermesEndpointType: "openai_compatible",
 39	    endpointFamily: "ollama",
 40	    scheme: "http",
 41	    laneFamily: "ollama",
 42	    v1Suffix: "/v1",
 43	    provider: (scope) =>
 44	      scope === "localhost" || scope === "loopback" ? "ollama-local" : "ollama",
 45	    supportsResidentModelInspection: true,
 46	  },
 47	  sglang: {
 48	    hermesEndpointType: "openai_compatible",
 49	    endpointFamily: "openai-compatible",
 50	    scheme: "http",
 51	    laneFamily: "openai-compatible",
 52	    v1Suffix: "/v1",
 53	    provider: () => "sglang-remote",
 54	    supportsResidentModelInspection: false,
 55	  },
 56	  "llama-cpp": {
 57	    hermesEndpointType: "openai_compatible",
 58	    endpointFamily: "openai-compatible",
 59	    scheme: "http",
 60	    laneFamily: "openai-compatible",
 61	    v1Suffix: "/v1",
 62	    provider: () => "llama-cpp-local",
 63	    supportsResidentModelInspection: false,
 64	  },
 65	  vllm: {
 66	    hermesEndpointType: "openai_compatible",
 67	    endpointFamily: "openai-compatible",
 68	    scheme: "http",
 69	    laneFamily: "openai-compatible",
 70	    v1Suffix: "/v1",
 71	    provider: () => "vllm",
 72	    supportsResidentModelInspection: false,
 73	  },
 74	  localai: {
 75	    hermesEndpointType: "openai_compatible",
 76	    endpointFamily: "openai-compatible",
 77	    scheme: "http",
 78	    laneFamily: "openai-compatible",
 79	    v1Suffix: "/v1",
 80	    provider: (scope) =>
 81	      scope === "localhost" || scope === "loopback" ? "localai-local" : "localai-remote",
 82	    supportsResidentModelInspection: false,
 83	  },
 84	};
 85	
 86	function fail(message) {
 87	  console.error(`generate-registries: ${message}`);
 88	  process.exit(2);
 89	}
 90	
 91	const examplePath = path.join(repoRoot, "inventory.example.json");
 92	
 93	if (!fs.existsSync(inventoryPath)) {
 94	  fail(
 95	    `no inventory.json found.\n  Start from the template:  cp inventory.example.json inventory.json`
 96	  );
 97	}
 98	
 99	const inventory = JSON.parse(fs.readFileSync(inventoryPath, "utf8"));
100	const exampleInventory = JSON.parse(fs.readFileSync(examplePath, "utf8"));
101	
102	// ── shared helpers ───────────────────────────────────────────────────────────
103	
104	function runtimeSpec(kind) {
105	  const spec = RUNTIMES[kind];
106	  if (!spec) {
107	    fail(`unknown runtime kind "${kind}". Known kinds: ${Object.keys(RUNTIMES).join(", ")}`);
108	  }
109	  return spec;
110	}
111	
112	function baseUrl(machine, runtime) {
113	  const spec = runtimeSpec(runtime.kind);
114	  return `${spec.scheme}://${machine.network.address}:${runtime.port}`;
115	}
116	
117	/** Tier id for a (machine, runtime) pair, matching policy.laneOrder vocabulary. */
118	function tierIdFor(machine, runtime) {
119	  const scope = machine.network.scope;
120	  const spec = runtimeSpec(runtime.kind);
121	  if (scope === "localhost" || scope === "loopback") return "local";
122	  if (scope === "tailscale") return `tailscale-${spec.laneFamily}`;
123	  return `${scope}-${spec.laneFamily}`;
124	}
125	
126	function hostIdFor(machine, runtime) {
127	  // A machine running one runtime keeps its own id; multiple runtimes get
128	  // suffixed so both are addressable and stable across regeneration.
129	  const siblings = machine.runtimes.filter((r) => r.enabled !== undefined);
130	  return siblings.length > 1 ? `${machine.id}-${runtime.kind}` : machine.id;
131	}
132	
133	function notesFor(machine, runtime) {
134	  return [machine.network.notes, runtime.notes].filter(Boolean).join(" ");
135	}
136	
137	// ── TS registry (platforms.json) ─────────────────────────────────────────────
138	
139	function buildTsHost(machine, runtime) {
140	  const spec = runtimeSpec(runtime.kind);
141	  const host = {
142	    id: hostIdFor(machine, runtime),
143	    label: `${machine.label}${machine.runtimes.length > 1 ? ` (${runtime.kind} lane)` : ""}`,
144	    provider: spec.provider(machine.network.scope),
145	    endpoint: baseUrl(machine, runtime),
146	    networkScope: machine.network.scope,
147	    enabled: runtime.enabled !== false,
148	  };
149	  if (runtime.primary) host.primary = true;
150	  if (runtime.reachable !== undefined) host.reachable = runtime.reachable;
151	
152	  host.capabilities = {
153	    endpointFamily: spec.endpointFamily,
154	    supportsResidentModelInspection: spec.supportsResidentModelInspection,
155	  };
156	  if (machine.execution) host.executionPolicy = { ...machine.execution };
157	  const notes = notesFor(machine, runtime);
158	  if (notes) host.connectionNotes = notes;
159	  if (machine.delegation) host.delegationPolicy = { ...machine.delegation };
160	  if (machine.hardware) host.hardware = JSON.parse(JSON.stringify(machine.hardware));
161	  host.models = JSON.parse(JSON.stringify(runtime.models ?? []));
162	  return host;
163	}
164	
165	function buildAggregatorHost(agg) {
166	  const host = {
167	    id: agg.id,
168	    label: agg.label,
169	    provider: `${agg.kind}-proxy`,
170	    endpoint: `http://${agg.network.address}:${agg.port}`,
171	    networkScope: agg.network.scope,
172	    enabled: agg.enabled !== false,
173	    capabilities: { endpointFamily: "openai-compatible", supportsResidentModelInspection: false },
174	  };
175	  if (agg.execution) host.executionPolicy = { ...agg.execution };
176	  if (agg.notes) host.connectionNotes = agg.notes;
177	  host.models = JSON.parse(JSON.stringify(agg.models ?? []));
178	  return host;
179	}
180	
181	function buildCloudHosts(cloud) {
182	  return (cloud?.providers ?? []).map((p) => ({
183	    id: p.id,
184	    label: p.label,
185	    provider: p.provider,
186	    endpoint: p.endpoint,
187	    networkScope: "internet",
188	    enabled: p.enabled === true,
189	    capabilities: { endpointFamily: "openai-compatible", supportsResidentModelInspection: false },
190	    ...(p.notes ? { connectionNotes: p.notes } : {}),
191	    models: p.models ?? [],
192	  }));
193	}
194	
195	function buildTsRegistry(inv) {
196	  const tiers = new Map();
197	  const ensureTier = (id, priority) => {
198	    if (!tiers.has(id)) tiers.set(id, { id, label: id, priority, hosts: [] });
199	    return tiers.get(id);
200	  };
201	
202	  const order = inv.policy.laneOrder;
203	  order.forEach((id, i) => ensureTier(id, i + 1));
204	
205	  for (const machine of inv.machines) {
206	    for (const runtime of machine.runtimes) {
207	      const tierId = tierIdFor(machine, runtime);
208	      const tier = ensureTier(tierId, order.indexOf(tierId) + 1 || order.length + 1);
209	      tier.hosts.push(buildTsHost(machine, runtime));
210	    }
211	  }
212	  for (const agg of inv.aggregators ?? []) {
213	    ensureTier("local", order.indexOf("local") + 1).hosts.push(buildAggregatorHost(agg));
214	  }
215	  const cloudHosts = buildCloudHosts(inv.cloud);
216	  if (cloudHosts.length) {
217	    ensureTier("cloud", order.indexOf("cloud") + 1).hosts.push(...cloudHosts);
218	  }
219	
220	  const ordered = order.map((id) => tiers.get(id)).filter(Boolean);
221	  for (const [id, tier] of tiers) if (!order.includes(id)) ordered.push(tier);
222	
223	  return {
224	    $schema: "./platforms.schema.json",
225	    version: 2,
226	    _generated:
227	      "Generated from inventory.json by xx-stack/scripts/generate-registries.mjs. Do not hand-edit; run `npm run inventory:sync`.",
228	    selectionPolicy: {
229	      defaultOrder: order,
230	      cloudEscalation: inv.policy.cloudEscalation,
231	      rules: inv.policy.rules ?? [],
232	    },
233	    tiers: ordered,
234	  };
235	}
236	
237	// ── Hermes lanes ─────────────────────────────────────────────────────────────
238	
239	function buildHermesLanes(inv) {
240	  const lanes = {};
241	  for (const machine of inv.machines) {
242	    for (const runtime of machine.runtimes) {
243	      // Hermes drives remote self-hosted inference; loopback runtimes are the
244	      // orchestrator's own host and are not lanes it dials out to.
245	      if (machine.network.scope === "localhost" || machine.network.scope === "loopback") continue;
246	      const spec = runtimeSpec(runtime.kind);
247	      const key = machine.runtimes.length > 1 ? runtime.kind : machine.id;
248	      lanes[key] = {
249	        name: `${machine.id}-${runtime.kind}`,
250	        role: "self_hosted",
251	        priority: runtime.hermesPriority ?? 50,
252	        endpoint_type: spec.hermesEndpointType,
253	        base_url: `${baseUrl(machine, runtime)}${spec.v1Suffix}`,
254	        model: runtime.models?.[0]?.name ?? null,
255	        enabled: runtime.enabled !== false,
256	      };
257	    }
258	  }
259	
260	  const cli = inv.cloud?.hermesCli;
261	  if (cli) {
262	    lanes.cloud = {
263	      name: cli.id,
264	      role: "cloud",
265	      priority: cli.hermesPriority ?? 10,
266	      endpoint_type: cli.endpointType,
267	      provider: cli.provider,
268	      base_url: cli.baseUrl,
269	      model: cli.model,
270	      fallback_models: cli.fallbackModels ?? [],
271	      catalog_models: [cli.model, ...(cli.fallbackModels ?? [])],
272	      chat_probe_on_models_failure: true,
273	      enabled: cli.enabled !== false,
274	    };
275	  }
276	  return lanes;
277	}
278	
279	// ── write / check ────────────────────────────────────────────────────────────
280	
281	const outputs = [];
282	
283	const tsRegistry = buildTsRegistry(inventory);
284	outputs.push({
285	  file: path.join(repoRoot, "opencode-orchestration", "opencode", "platforms.json"),
286	  content: JSON.stringify(tsRegistry, null, 2) + "\n",
287	});
288	
289	// xx-stack/ is the host-agnostic core, so the registry it SHIPS is built from
290	// the template, not from your machines. Otherwise every clone of this repo
291	// would carry the maintainer's hardware as its default.
292	outputs.push({
293	  file: path.join(repoRoot, "xx-stack", "runtime", "platforms.json"),
294	  content: JSON.stringify(buildTsRegistry(exampleInventory), null, 2) + "\n",
295	});
296	
297	// Hermes: replace only the lanes block, preserve hand-tuned policy/execution/proxy.
298	const hermesPath = path.join(repoRoot, "hermes-orchestration", "config", "orchestration.json");
299	const hermes = JSON.parse(fs.readFileSync(hermesPath, "utf8"));
300	hermes.lanes = buildHermesLanes(inventory);
301	hermes.policy = {
302	  ...hermes.policy,
303	  self_hosted_first: inventory.policy.selfHostedFirst !== false,
304	  cloud_enabled_by_default: inventory.policy.cloudEscalation.optIn === true,
305	  require_manual_cloud_escalation: inventory.policy.cloudEscalation.optIn !== true,
306	  primary_lane_order: Object.keys(hermes.lanes),
307	};
308	outputs.push({ file: hermesPath, content: JSON.stringify(hermes, null, 2) + "\n" });
309	
310	let stale = 0;
311	for (const { file, content } of outputs) {
312	  const rel = path.relative(repoRoot, file);
313	  const current = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : null;
314	  if (current === content) {
315	    console.log(`  ok     ${rel}`);
316	    continue;
317	  }
318	  if (checkOnly) {
319	    console.log(`  STALE  ${rel}`);
320	    stale++;
321	  } else {
322	    fs.writeFileSync(file, content, "utf8");
323	    console.log(`  wrote  ${rel}`);
324	  }
325	}
326	
327	if (checkOnly && stale > 0) {
328	  console.error(`\n${stale} generated file(s) are stale. Run: npm run inventory:sync`);
329	  process.exitCode = 1;
330	} else if (checkOnly) {
331	  console.log("\nAll generated registries are current.");
332	}
