  1	import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
  2	import { z } from "zod";
  3	
  4	import { logEvent } from "./log_worker.js";
  5	import type { Registry } from "./platform_types.js";
  6	import { buildWatchdogRouteCandidates, routeParallelTasks, routeTask } from "./routing_runtime.js";
  7	
  8	import { jsonContent } from "./agent_tool_helpers.js";
  9	interface RoutingToolDeps {
 10	  loadRegistry: () => Promise<Registry>;
 11	}
 12	
 13	export function registerRoutingTools(server: McpServer, deps: RoutingToolDeps): void {
 14	  server.tool(
 15	    "route_task",
 16	    "Given a task description, recommend which platform tier, host, and model to use",
 17	    { description: z.string().describe("Description of the task to route") },
 18	    async ({ description }) => {
 19	      const registry = await deps.loadRegistry();
 20	      const result = routeTask(description, registry);
 21	      void logEvent("server", "route_task.result", {
 22	        description: description.slice(0, 200),
 23	        tier: result.recommendedTier,
 24	        host: result.recommendedHost,
 25	        model: result.recommendedModel,
 26	        fallback: result.fallback,
 27	        reasoning: result.reasoning,
 28	      });
 29	      return jsonContent(result);
 30	    }
 31	  );
 32	
 33	  server.tool(
 34	    "route_parallel_tasks",
 35	    "Given multiple task descriptions, produce a hardware-aware parallel delegation schedule across local and remote hosts",
 36	    {
 37	      tasks: z
 38	        .array(z.string())
 39	        .min(1)
 40	        .max(128)
 41	        .describe("Task descriptions to schedule in parallel"),
 42	    },
 43	    async ({ tasks }) => {
 44	      const registry = await deps.loadRegistry();
 45	      const schedule = routeParallelTasks(tasks, registry);
 46	      const assignments = schedule.assignments as Array<Record<string, unknown>>;
 47	      void logEvent("server", "route_parallel_tasks.result", {
 48	        taskCount: tasks.length,
 49	        assignedCount: assignments.filter((a) => a["status"] !== "unassigned").length,
 50	        unassignedCount: assignments.filter((a) => a["status"] === "unassigned").length,
 51	        hostUtilization: schedule.hostUtilization,
 52	      });
 53	      return jsonContent(schedule);
 54	    }
 55	  );
 56	
 57	  server.tool(
 58	    "route_task_with_watchdog",
 59	    "Route a task with host/model liveness checks and automatic failover recommendations",
 60	    {
 61	      description: z.string().describe("Description of the task to route"),
 62	      preferredHost: z
 63	        .string()
 64	        .optional()
 65	        .describe("Optional host ID override for the primary attempt"),
 66	      preferredModel: z
 67	        .string()
 68	        .optional()
 69	        .describe("Optional model override for the primary attempt"),
 70	      maxFallbacks: z
 71	        .number()
 72	        .int()
 73	        .min(1)
 74	        .max(8)
 75	        .optional()
 76	        .describe("Maximum fallback hosts to probe"),
 77	    },
 78	    async ({ description, preferredHost, preferredModel, maxFallbacks }) => {
 79	      const registry = await deps.loadRegistry();
 80	      const baseRoute = routeTask(description, registry);
 81	      const candidates = await buildWatchdogRouteCandidates(
 82	        registry,
 83	        description,
 84	        preferredHost ?? null,
 85	        preferredModel ?? null,
 86	        maxFallbacks ?? 3,
 87	        new Set<string>()
 88	      );
 89	
 90	      const selectedFailover = candidates.candidates[0] ?? null;
 91	      const primaryHealthy = candidates.healthyPrimary;
 92	      const status = primaryHealthy ? "healthy" : selectedFailover ? "degraded" : "unavailable";
 93	      const primaryHealth =
 94	        candidates.health.find((entry) => (entry as { kind?: string }).kind === "primary") ?? null;
 95	      const failoverCandidates = candidates.health.filter(
 96	        (entry) => (entry as { kind?: string }).kind === "fallback"
 97	      );
 98	      const reason = primaryHealthy
 99	        ? "Primary route passed liveness checks"
100	        : selectedFailover
101	          ? "Primary route failed liveness checks; failover candidate selected"
102	          : "Primary route failed and no healthy failover was found";
103	
104	      void logEvent("server", "route_task_with_watchdog.result", {
105	        description: description.slice(0, 200),
106	        status,
107	        primaryHost: candidates.primary?.host ?? null,
108	        primaryModel: candidates.primary?.model ?? null,
109	        selectedFailoverHost: selectedFailover?.host ?? null,
110	        fallbackCount: candidates.candidates.length,
111	      });
112	
113	      return jsonContent({
114	        status,
115	        reason,
116	        baseRoute,
117	        primary: candidates.primary
118	          ? {
119	              ...candidates.primary,
120	              health: primaryHealth
121	                ? ((primaryHealth as { health?: unknown }).health ?? null)
122	                : null,
123	            }
124	          : null,
125	        selectedFailover,
126	        failoverCandidates,
127	      });
128	    }
129	  );
130	}
