 42	function parseLifecycleHookSpecs(rawHooks: unknown): Record<string, LifecycleHookSpec[]> {
 43	  const source = asRecord(rawHooks);
 44	  const parsed: Record<string, LifecycleHookSpec[]> = {};
 45	
 46	  for (const [eventName, eventHooks] of Object.entries(source)) {
 47	    if (!Array.isArray(eventHooks)) continue;
 48	    const specs: LifecycleHookSpec[] = [];
 49	
 50	    for (const rawSpec of eventHooks) {
 51	      const specRecord = asRecord(rawSpec);
 52	      const command = typeof specRecord.command === "string" ? specRecord.command.trim() : "";
 53	      if (!command) continue;
 54	      const args = toStringArray(specRecord.args).slice(0, MAX_EXEC_ARG_COUNT);
 55	      const timeoutMs = Math.min(
 56	        120_000,
 57	        Math.max(500, Math.floor(toPositiveNumber(specRecord.timeoutMs, 5_000)))
 58	      );
 59	      const cwd = typeof specRecord.cwd === "string" ? specRecord.cwd.trim() : "";
 60	      const allowFailure =
 61	        typeof specRecord.allowFailure === "boolean" ? specRecord.allowFailure : true;
 62	      specs.push({
 63	        command,
 64	        args,
 65	        timeoutMs,
 66	        cwd: cwd.length > 0 ? cwd : undefined,
 67	        allowFailure,
 68	      });
 69	    }
 70	
 71	    if (specs.length > 0) {
 72	      parsed[eventName] = specs;
 73	    }
 74	  }
 75	
 76	  return parsed;
 77	}
 78	
 79	function parseLifecycleHooksConfigFromRoot(root: Record<string, unknown> | null): {
 80	  enabled: boolean | undefined;
 81	  allowedCommands: string[];
 82	  events: Record<string, LifecycleHookSpec[]>;
 83	} {
 84	  if (!root) {
 85	    return { enabled: undefined, allowedCommands: [], events: {} };
 86	  }
 87	  const lifecycleHooks = asRecord(root.lifecycleHooks);
 88	  return {
 89	    enabled: typeof lifecycleHooks.enabled === "boolean" ? lifecycleHooks.enabled : undefined,
 90	    allowedCommands: toStringArray(lifecycleHooks.allowedCommands),
 91	    events: parseLifecycleHookSpecs(lifecycleHooks.events),
 92	  };
 93	}
 94	
 95	async function loadLifecycleHooksConfig(): Promise<LifecycleHooksConfig> {
 96	  const repoPath = getRepoConfigPath();
 97	  const userPath = getUserConfigPath();
 98	  const [repoRoot, userRoot] = await Promise.all([readJson(repoPath), readJson(userPath)]);
 99	  const repoConfig = parseLifecycleHooksConfigFromRoot(repoRoot);
100	  const userConfig = parseLifecycleHooksConfigFromRoot(userRoot);
101	  const enabled = userConfig.enabled ?? repoConfig.enabled ?? false;
102	  const allowedCommands = [
103	    ...new Set([
104	      ...repoConfig.allowedCommands.map((value) => value.trim()).filter(Boolean),
105	      ...userConfig.allowedCommands.map((value) => value.trim()).filter(Boolean),
106	    ]),
107	  ];
108	
109	  const events: Record<string, LifecycleHookSpec[]> = {};
110	  const eventNames = new Set([
111	    ...Object.keys(repoConfig.events),
112	    ...Object.keys(userConfig.events),
113	  ]);
114	  for (const eventName of eventNames) {
115	    events[eventName] = [
116	      ...(repoConfig.events[eventName] ?? []),
117	      ...(userConfig.events[eventName] ?? []),
118	    ];
119	  }
120	
121	  return {
122	    enabled,
123	    allowedCommands,
124	    events,
125	    sources: { repoPath, userPath },
126	  };
127	}
