 11	} from "./config_runtime.js";
 12	
 13	const execFileAsync = promisify(execFile);
 14	const MAX_EXEC_ARG_COUNT = 32;
 15	const MAX_EXEC_ARG_LENGTH = 1024;
 16	const SAFE_HOOK_ARG_PATTERN = /^[a-zA-Z0-9_./:@%+=,-]+$/;
 17	export const INTERNAL_VRAM_PROBE =
 18	  "cat /sys/class/drm/card*/device/mem_info_vram_total 2>/dev/null";
 19	
 20	interface LifecycleHookSpec {
 21	  command: string;
 22	  args: string[];
 23	  timeoutMs: number;
 24	  cwd?: string;
 25	  allowFailure: boolean;
 26	}
 27	
 28	interface LifecycleHooksConfig {
 29	  enabled: boolean;
 30	  allowedCommands: string[];
 31	  events: Record<string, LifecycleHookSpec[]>;
 32	  sources: { repoPath: string; userPath: string };
 33	}
 34	
 35	type ExecValidationContext = "internal" | "hook";
 36	
 37	interface ExecValidationResult {
 38	  allowed: boolean;
 39	  reason: string;
 40	}
 41	
 42	function parseLifecycleHookSpecs(rawHooks: unknown): Record<string, LifecycleHookSpec[]> {
 43	  const source = asRecord(rawHooks);
 44	  const parsed: Record<string, LifecycleHookSpec[]> = {};
 45	
 46	  for (const [eventName, eventHooks] of Object.entries(source)) {
 47	    if (!Array.isArray(eventHooks)) continue;
 48	    const specs: LifecycleHookSpec[] = [];
 49	
 50	    for (const rawSpec of eventHooks) {
 51	      const specRecord = asRecord(rawSpec);
 52	      const command = typeof specRecord.command === "string" ? specRecord.command.trim() : "";
 53	      if (!command) continue;
 54	      const args = toStringArray(specRecord.args).slice(0, MAX_EXEC_ARG_COUNT);
 55	      const timeoutMs = Math.min(
 56	        120_000,
 57	        Math.max(500, Math.floor(toPositiveNumber(specRecord.timeoutMs, 5_000)))
 58	      );
 59	      const cwd = typeof specRecord.cwd === "string" ? specRecord.cwd.trim() : "";
 60	      const allowFailure =
 61	        typeof specRecord.allowFailure === "boolean" ? specRecord.allowFailure : true;
 62	      specs.push({
 63	        command,
 64	        args,
 65	        timeoutMs,
 66	        cwd: cwd.length > 0 ? cwd : undefined,
 67	        allowFailure,
 68	      });
 69	    }
 70	
 71	    if (specs.length > 0) {
 72	      parsed[eventName] = specs;
 73	    }
 74	  }
 75	
 76	  return parsed;
 77	}
 78	
 79	function parseLifecycleHooksConfigFromRoot(root: Record<string, unknown> | null): {
 80	  enabled: boolean | undefined;
 81	  allowedCommands: string[];
 82	  events: Record<string, LifecycleHookSpec[]>;
 83	} {
 84	  if (!root) {
 85	    return { enabled: undefined, allowedCommands: [], events: {} };
 86	  }
 87	  const lifecycleHooks = asRecord(root.lifecycleHooks);
 88	  return {
 89	    enabled: typeof lifecycleHooks.enabled === "boolean" ? lifecycleHooks.enabled : undefined,
 90	    allowedCommands: toStringArray(lifecycleHooks.allowedCommands),
 91	    events: parseLifecycleHookSpecs(lifecycleHooks.events),
 92	  };
 93	}
 94	
 95	async function loadLifecycleHooksConfig(): Promise<LifecycleHooksConfig> {
 96	  const repoPath = getRepoConfigPath();
 97	  const userPath = getUserConfigPath();
 98	  const [repoRoot, userRoot] = await Promise.all([readJson(repoPath), readJson(userPath)]);
 99	  const repoConfig = parseLifecycleHooksConfigFromRoot(repoRoot);
100	  const userConfig = parseLifecycleHooksConfigFromRoot(userRoot);
101	  const enabled = userConfig.enabled ?? repoConfig.enabled ?? false;
102	  const allowedCommands = [
103	    ...new Set([
104	      ...repoConfig.allowedCommands.map((value) => value.trim()).filter(Boolean),
105	      ...userConfig.allowedCommands.map((value) => value.trim()).filter(Boolean),
106	    ]),
107	  ];
108	
109	  const events: Record<string, LifecycleHookSpec[]> = {};
110	  const eventNames = new Set([
111	    ...Object.keys(repoConfig.events),
112	    ...Object.keys(userConfig.events),
113	  ]);
114	  for (const eventName of eventNames) {
115	    events[eventName] = [
116	      ...(repoConfig.events[eventName] ?? []),
117	      ...(userConfig.events[eventName] ?? []),
118	    ];
119	  }
120	
121	  return {
122	    enabled,
123	    allowedCommands,
124	    events,
125	    sources: { repoPath, userPath },
126	  };
127	}
128	
129	export function validateExecRequest(
130	  command: string,
131	  args: string[],
132	  context: ExecValidationContext,
133	  allowedHookCommands: string[] = []
134	): ExecValidationResult {
135	  const normalizedCommand = command.trim();
136	  if (!normalizedCommand) {
137	    return { allowed: false, reason: "empty_command" };
138	  }
139	
140	  if (args.length > MAX_EXEC_ARG_COUNT) {
141	    return { allowed: false, reason: "too_many_args" };
142	  }
143	
144	  if (args.some((arg) => arg.length > MAX_EXEC_ARG_LENGTH)) {
145	    return { allowed: false, reason: "arg_too_long" };
146	  }
147	
148	  if (context === "internal") {
149	    if (normalizedCommand === "free") {
150	      return args.length === 1 && args[0] === "-b"
151	        ? { allowed: true, reason: "ok" }
152	        : { allowed: false, reason: "internal_free_args_invalid" };
153	    }
154	    if (normalizedCommand === "lspci") {
155	      return args.length === 0
156	        ? { allowed: true, reason: "ok" }
157	        : { allowed: false, reason: "internal_lspci_args_invalid" };
158	    }
159	    if (normalizedCommand === "bash") {
160	      return args.length === 2 && args[0] === "-c" && args[1] === INTERNAL_VRAM_PROBE
161	        ? { allowed: true, reason: "ok" }
162	        : { allowed: false, reason: "internal_bash_args_invalid" };
163	    }
164	    return { allowed: false, reason: "internal_command_not_allowlisted" };
165	  }
166	
167	  const allowlist = new Set(allowedHookCommands.map((entry) => entry.trim()).filter(Boolean));
168	  if (!allowlist.has(normalizedCommand)) {
169	    return { allowed: false, reason: "hook_command_not_allowlisted" };
170	  }
171	
172	  if (args.some((arg) => !SAFE_HOOK_ARG_PATTERN.test(arg))) {
173	    return { allowed: false, reason: "hook_arg_pattern_blocked" };
174	  }
175	
176	  return { allowed: true, reason: "ok" };
177	}
178	
179	export async function guardedExecFile(
180	  command: string,
181	  args: string[],
182	  options: { timeout?: number; cwd?: string; env?: NodeJS.ProcessEnv } = {},
183	  guard: { context: ExecValidationContext; allowedHookCommands?: string[] }
184	): Promise<{ stdout: string; stderr: string }> {
185	  const validation = validateExecRequest(
186	    command,
187	    args,
188	    guard.context,
189	    guard.allowedHookCommands ?? []
190	  );
191	  if (!validation.allowed) {
192	    throw new Error(`execution_policy_denied:${validation.reason}`);
193	  }
194	  return execFileAsync(command, args, options);
195	}
196	
197	export async function emitLifecycleHooks(
198	  eventName: string,
199	  payload: Record<string, unknown>
200	): Promise<{
201	  enabled: boolean;
202	  eventName: string;
203	  configuredHookCount: number;
204	  executedHookCount: number;
205	  blockedHookCount: number;
206	  failedHookCount: number;
207	  results: Array<Record<string, unknown>>;
208	}> {
209	  const config = await loadLifecycleHooksConfig();
210	  const hooks = config.events[eventName] ?? [];
211	
212	  if (!config.enabled || hooks.length === 0) {
213	    return {
214	      enabled: config.enabled,
215	      eventName,
216	      configuredHookCount: hooks.length,
217	      executedHookCount: 0,
218	      blockedHookCount: 0,
219	      failedHookCount: 0,
220	      results: [],
221	    };
222	  }
223	
224	  const results: Array<Record<string, unknown>> = [];
225	  let executedHookCount = 0;
226	  let blockedHookCount = 0;
227	  let failedHookCount = 0;
228	
229	  for (const hook of hooks) {
230	    const validation = validateExecRequest(hook.command, hook.args, "hook", config.allowedCommands);
231	    if (!validation.allowed) {
232	      blockedHookCount += 1;
233	      const blocked = {
234	        command: hook.command,
235	        args: hook.args,
236	        status: "blocked",
237	        reason: validation.reason,
238	      };
239	      results.push(blocked);
240	      if (!hook.allowFailure) {
241	        throw new Error(`lifecycle_hook_blocked:${hook.command}:${validation.reason}`);
242	      }
243	      continue;
244	    }
245	
246	    try {
247	      const startedAt = Date.now();
248	      const hookEnv: NodeJS.ProcessEnv = {
249	        ...process.env,
250	        XX_STACK_HOOK_EVENT: eventName,
251	        XX_STACK_HOOK_SESSION_ID: String(payload.sessionId ?? ""),
252	        XX_STACK_HOOK_TASK_ID: String(payload.taskId ?? ""),
253	      };
254	      const { stdout, stderr } = await guardedExecFile(
255	        hook.command,
256	        hook.args,
257	        { timeout: hook.timeoutMs, cwd: hook.cwd, env: hookEnv },
258	        { context: "hook", allowedHookCommands: config.allowedCommands }
259	      );
260	      executedHookCount += 1;
261	      results.push({
262	        command: hook.command,
263	        args: hook.args,
264	        status: "ok",
265	        durationMs: Date.now() - startedAt,
266	        stdout: stdout.trim(),
267	        stderr: stderr.trim(),
268	      });
269	    } catch (error) {
270	      failedHookCount += 1;
271	      const message = error instanceof Error ? error.message : String(error);
272	      const failed = {
273	        command: hook.command,
274	        args: hook.args,
275	        status: "failed",
276	        error: message,
277	      };
278	      results.push(failed);
279	      if (!hook.allowFailure) {
280	        throw new Error(`lifecycle_hook_failed:${hook.command}:${message}`);
281	      }
282	    }
283	  }
284	
285	  return {
286	    enabled: true,
287	    eventName,
288	    configuredHookCount: hooks.length,
289	    executedHookCount,
290	    blockedHookCount,
291	    failedHookCount,
292	    results,
293	  };
294	}
